    case "search": {
      const found = hits();
      const pageSize = Math.max(
        1,
        Math.min(100, Number(values.pageSize ?? values.limit ?? 10) || 10),
      );
      const page = Math.max(
        0,
        Number(values.page ?? values.pageIndex ?? 0) || 0,
      );
      return {
        kind: "search",
        hits: found.slice(page * pageSize, (page + 1) * pageSize),
        total: found.length,
        facets: ["type", "status"].map((key) => {
