          for (const record of matching) {
            const value = key === "type" ? record.type : record.status;
            counts.set(value, (counts.get(value) ?? 0) + 1);
          }
          return {
            id: key,
            label: key === "type" ? "Record type" : "Status",
            selection: "multiple",
