    if (parsed.search || parsed.hash) return false;
    let path = parsed.pathname;
    for (let pass = 0; pass < 2; pass++) path = decodeURIComponent(path);
    return !path.startsWith("//") && !/[\u0000-\u0020\u007f\\]/.test(path);
